/* Fontes do relatório em PDF, embutidas para o jsPDF (TTF em base64, só o latim com acentos do português).
   Figtree 500 e 700 (OFL, Erik Kennedy) e Hedvig Letters Serif 400 (OFL, Hedvig Letters). Gerado por conversão do woff2 da página.
   Também traz o avatar da pílula (JPEG de 96 px já recortado em círculo sobre a cor da pílula). */
window.PDF_AVATAR = "data:image/jpeg;base64,";
window.registrarFontesPDF = function(doc){
  doc.addFileToVFS("Figtree-Medium.ttf", "");
  doc.addFont("Figtree-Medium.ttf", "Figtree", "normal");
  doc.addFileToVFS("Figtree-Bold.ttf", "");
  doc.addFont("Figtree-Bold.ttf", "Figtree", "bold");
  doc.addFileToVFS("HedvigLettersSerif-Regular.ttf", "");
  doc.addFont("HedvigLettersSerif-Regular.ttf", "Hedvig Letters Serif", "normal");
  return true;
};
